'use client';

import { useState } from 'react';

export default function Navbar({ aiOnline }) {
  const [activeNav, setActiveNav] = useState('dashboard');

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: '⬡' },
    { id: 'alerts', label: 'Alerts', icon: '◈' },
    { id: 'settings', label: 'Settings', icon: '◎' },
  ];

  return (
    <nav className="navbar">
      {/* Logo */}
      <div className="navbar-logo">
        <div className="navbar-logo-icon">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
            <path d="M12 2L2 7l10 5 10-5-10-5z" stroke="#22c55e" strokeWidth="1.5" strokeLinejoin="round"/>
            <path d="M2 17l10 5 10-5" stroke="#22c55e" strokeWidth="1.5" strokeLinejoin="round"/>
            <path d="M2 12l10 5 10-5" stroke="#22c55e" strokeWidth="1.5" strokeLinejoin="round"/>
          </svg>
        </div>
        <div>
          <div className="navbar-logo-text">Criminal Detector AI</div>
          <div className="navbar-logo-sub">Neural Surveillance System v4.2</div>
        </div>
      </div>

      {/* Nav Items */}
      <div className="navbar-nav">
        {navItems.map(item => (
          <button
            key={item.id}
            className={`nav-item ${activeNav === item.id ? 'active' : ''}`}
            onClick={() => setActiveNav(item.id)}
          >
            <span>{item.icon}</span>
            {item.label}
          </button>
        ))}
      </div>

      {/* AI Status */}
      <div className="navbar-status">
        <div className={`status-dot ${aiOnline ? '' : 'offline'}`} />
        <span>AI DETECTION {aiOnline ? 'ACTIVE' : 'OFFLINE'}</span>
      </div>
    </nav>
  );
}
